nextflow_process {

    name "Test Process RSEQC_INNERDISTANCE"
    script "../main.nf"
    process "RSEQC_INNERDISTANCE"

    tag "modules"
    tag "modules_nfcore"
    tag "rseqc"
    tag "rseqc/innerdistance"

    test("sarscov2 - [[meta] - bam] - bed") {

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = channel.of(file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.pdf[0][1]).name,
                    process.out.distance,
                    process.out.freq,
                    process.out.mean,
                    process.out.rscript,
                    process.out.versions_rseqc
                ).match() }
            )
        }
    }

    test("sarscov2 - [[meta] - bam] - bed - stub") {

    options "-stub"

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = channel.of(file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true))
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() },
                { assert snapshot(process.out.versions_rseqc).match("versions") }
            )
        }
    }
}
